"""Update the pack's Russian documentation after the modular fitting revision."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
pack = root / 'public/asset-packs/chibi-tokens-v1'
prompts = json.loads((pack / 'prompts.json').read_text(encoding='utf-8'))
prompts.update(json.loads((pack / 'expansion-prompts.json').read_text(encoding='utf-8')))
for key, filename in [('face_expansion', 'face-plus-prompt.txt'), ('hair_expansion', 'hair-plus-prompt.txt'), ('head_shapes', 'heads-prompt.txt')]:
    prompts[key] = (pack / filename).read_text(encoding='utf-8')
(pack / 'prompts.json').write_text(json.dumps(prompts, ensure_ascii=False, indent=2), encoding='utf-8')

help_file = root / 'src/data/helpContent.ts'
lines = help_file.read_text(encoding='utf-8').splitlines()
for i, line in enumerate(lines):
    if '"id": "chibi-pack"' not in line:
        continue
    topic = json.loads(line.strip().rstrip(','))
    topic['summary'] = '4 основы кожи, 168 сменных модулей, 34 клипа. Откройте «Чиби-пак» в левой навигации.'
    topic['steps'] = [
        'Сначала выберите «Пол»: мужской или женский. Доступны 8 мужских, 12 женских и 4 общих причёски; бороды и усы доступны только мужчинам. Ручной выбор, стрелки и случайная внешность учитывают пол. Смена пола снимает несовместимые детали и сохраняется вместе с персонажем.',
        'Конструктор занимает всю страницу. Кнопки ‹ и › рядом со списками переключают варианты по кругу, включая «Без элемента». В выбранном списке также работают клавиши ← и →.',
        '«Случайная внешность» выбирает кожу, форму головы, глаза, брови, волосы и черты лица. Брови выбираются всегда; глаза с уже нарисованными бровями исключены из случайного выбора. Одежда, головные уборы, украшения и все предметы снимаются; подгонка сбрасывается. Имя и анимация сохраняются. До «Добавить персонажа» или «Применить изменения» результат существует только в конструкторе.',
        'Выберите основу и форму головы / ушей, затем глаза, брови, нос, рот, причёску, одежду и шлем. «Без элемента» убирает модуль; «Чистая основа» снимает все детали.',
        'Для бороды, шапки и любой другой детали используйте «Подгонка детали»: ширина и высота в процентах, сдвиг по горизонтали и вертикали, поворот. Изменения сразу видны. «Сбросить подгонку детали» возвращает исходный размер и положение.',
        'Причёски, бороды и головные уборы автоматически следуют ширине выбранной формы головы. Личная подгонка применяется поверх этого размера. Доступны 24 причёски, 14 бород и усов, 25 вариантов глаз, 18 ртов, 10 носов, 16 бровей, 6 шрамов, 3 набора веснушек и 2 варианта родинок.',
        'Рот автоматически помещается в отверстие под усами; борода перекрывает его края. Подгонка рта добавляется к этому положению. Головной убор скрывает волосы и лишние участки головы; его снятие возвращает причёску. Шрамы находятся на щеке и не рисуются поверх глаз.',
        '«Эмоция» задаёт выражение лица: «По анимации», «Спокойствие», «Радость», «Злость», «Грусть» или «Удивление». В автоматическом режиме танец радостный, возмущение и удары сердитые, падение и прыжок удивлённые; торговля сопровождается движением рта.',
        'Флажки «Моргание» и «Движение рта» включают соответствующие движения. Моргание видно в клипах длиной от 1,2 секунды; короткие циклы ходьбы и бега не заставляют глаза моргать на каждом шаге. При смерти глаза закрываются после первой трети клипа. Отсутствующие глаза, брови или рот не добавляются.',
        'Настройки лица сохраняются кнопкой «Добавить персонажа» или «Применить изменения», затем «Сохранить». Эмоции одинаково работают в конструкторе, предпросмотре и экспортированных кадрах. Ползунок «Время анимации» позволяет проверить фазу моргания или открытия рта.',
        'Выбор «Анимация» никогда не меняет предметы. Выберите оружие, стрелу, мешок, ящик, укрытие или крючок вручную. «Без элемента» оставляет соответствующее движение без предмета.',
        'Щит привязан к корпусу и движется вместе с ним. Лук, копьё, двуручный меч и мотыга занимают обе руки: выбор такого предмета снимает щит. Выбор щита снимает двуручный предмет.',
        '«Исходная поза» возвращает время в ноль; ползунок показывает отдельные фазы. Кнопка направления включает зеркальное отражение.',
        '«Добавить персонажа» добавляет чиби, модули и клипы в текущий проект. Существующие объекты сохраняются; действие можно отменить.',
        'Чтобы изменить активного чиби, откройте «Чиби-пак» снова либо «Внешность → Изменить чиби». «Применить изменения» сохраняет подгонку и выбранные детали; «Новый персонаж» начинает следующего.',
        'Цвета растровых деталей фиксированы. Доступны четыре кожи и четыре формы головы с разными ушами для каждой кожи. Форму головы и волосы можно подогнать по размеру.',
        'Рисунки головы и корпуса открываются в «Части и рисунки». Исходный растровый модуль сохраняется; рисуйте правки на новом слое.',
        '«Сохранить» сохраняет проект вместе с PNG и подгонкой. «Скачать весь ассет-пак ZIP» даёт исходные атласы, JSON, готовые PNG-анимации и пример проекта. Собственный внешний вид экспортируйте через «Экспортировать».',
        'Первая версия содержит один ракурс и зеркальный вид. Урон, коллизии, инвентарь и перенос предмета в мир задаются кодом игры.'
    ]
    lines[i] = '  ' + json.dumps(topic, ensure_ascii=False) + ','
help_file.write_text('\n'.join(lines) + '\n', encoding='utf-8')

readme = pack / 'README.ru.md'
text = readme.read_text(encoding='utf-8')
text = text.replace('112 сменных модулей: 40 деталей лица, 16 причёсок, 16 форм головы / ушей (4 формы × 4 кожи), 8 комплектов одежды/брони, 8 головных уборов, 8 оружейных элементов, 8 бытовых предметов, 8 бород и аксессуаров.', '168 сменных модулей: 80 деталей лица, 24 причёски, 16 форм головы / ушей (4 формы × 4 кожи), 8 комплектов одежды/брони, 8 головных уборов, 8 оружейных элементов, 8 бытовых предметов, 16 бород и аксессуаров.')
text = text.replace('64 сменных модуля: 16 деталей лица, 8 причёсок, 8 комплектов одежды/брони, 8 головных уборов, 8 оружейных элементов, 8 бытовых предметов, 8 бород и аксессуаров.', '112 сменных модулей: 40 деталей лица, 16 причёсок, 16 форм головы / ушей (4 формы × 4 кожи), 8 комплектов одежды/брони, 8 головных уборов, 8 оружейных элементов, 8 бытовых предметов, 8 бород и аксессуаров.')
text = text.replace('В «Анимация» выберите действие. Для удара автоматически подставляется нужное оружие. Для переноски — ящик, для вспашки — мотыга, для торговли — кошелёк. Предмет можно заменить вручную.', 'В «Анимация» выберите действие. Анимация не меняет выбранные предметы. Оружие, стрелу, ящик, мешок, укрытие или крючок выберите вручную в соответствующем списке; «Без элемента» оставляет движение без предмета.')
text = text.replace('Для открытого шлема или капюшона снимите слишком объёмную причёску; каждый вариант волос не обязан помещаться под каждым шлемом.', 'Любой головной убор скрывает волосы; снятие возвращает выбранную причёску. Посадку шапки настройте в «Подгонка детали».')
text = text.replace('## Формат для использования вне редактора', '## Подгонка деталей\n\nВыберите деталь справа, затем настройте «Подгонка детали»: ширину, высоту, сдвиг по горизонтали / вертикали и поворот. Масштабирование происходит вокруг центра детали. Рот выбирается отдельно и помещается под усами. Для шапки обычно нужны высота и сдвиг по вертикали. «Сбросить подгонку детали» возвращает исходные параметры. «Применить изменения» сохраняет подгонку на персонаже; затем «Сохранить» записывает проект. Для последующей правки снова откройте «Чиби-пак».\n\nЩит следует корпусу. Лук, копьё, двуручный меч и мотыга несовместимы со щитом: последняя выбранная деталь снимает конфликтующую. В обычной «Экипировка» действует то же правило, с отменой через Undo.\n\n## Формат для использования вне редактора') if '## Подгонка деталей' not in text else text
readme.write_text(text, encoding='utf-8')
